def kth_smallest(mat, k):
    sums = [0]
    for row in mat:
        sums = heapq.nsmallest(k, (s + v for s in sums for v in row))
    return sums[-1]

def kth_smallest(mat, k):
    m, n = len(mat), len(mat[0])
    start = tuple([0] * m)
    first = sum(row[0] for row in mat)
    heap = [(first, start)]
    seen = {start}

    for _ in range(k - 1):
        total, idx = heapq.heappop(heap)
        for r in range(m):
            if idx[r] + 1 < n:
                nxt = idx[:r] + (idx[r] + 1,) + idx[r + 1:]
                if nxt not in seen:
                    seen.add(nxt)
                    heapq.heappush(
                        heap, (total - mat[r][idx[r]] + mat[r][idx[r] + 1], nxt))
    return heap[0][0]
